#![allow(clippy::excessive_precision)]
//! Golden-parity tests for cartalith-civ's affordance fields (lithology,
//! soil fertility, water access) against the real reference engine.
//! PHASE2_SCOPE.md milestone 1. Generated from a Node `vm` extraction run
//! against `reference/Cartalith Gen1 v2.10.html` -- same technique/
//! discipline as every other golden test in this workspace (harness itself
//! is transient, not checked in). Cases reuse
//! `cartalith-engine/tests/golden_parity_carve.rs`'s exact fixture
//! configs (gw/gh/seed/world/w_iters=12) so this doubles as a cross-check
//! that both extractions agree on the same underlying generate() run.
//!
//! Lithology is a categorical classification -- bit-exact match required,
//! any mismatch is a real bug, not a rounding question. Soil fertility and
//! water access are continuous `f32` fields -- `1e-4` absolute+relative
//! tolerance, matching `golden_parity_carve.rs`'s own convention for
//! fields downstream of `Math.hypot`-derived slope/distance terms (not
//! required to be bit-identical across JS/Rust, ECMA-262
//! "implementation-approximated").

fn assert_close(actual: &[f32], expected: &[f32], label: &str) {
    const ATOL: f32 = 1e-4;
    const RTOL: f32 = 1e-4;
    for (i, (&a, &e)) in actual.iter().zip(expected.iter()).enumerate() {
        let tol = ATOL + RTOL * e.abs();
        assert!(
            (a - e).abs() <= tol,
            "{label} index {i}: got {a}, expected {e} (diff {}, tol {tol})",
            (a - e).abs()
        );
    }
    assert_eq!(actual.len(), expected.len(), "{label}: length mismatch");
}

